.hhead{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.hhead .sub-t{margin:0}
.hpick{display:flex;align-items:center;gap:6px;font-size:13.5px;color:var(--mut);margin-inline-start:auto}
.hpick input{min-height:36px}
.hday{border-bottom:1px solid var(--line)}
.hday summary{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;cursor:pointer;list-style:none}
.hday summary::-webkit-details-marker{display:none}
.hday summary::before{content:'▸';color:var(--mut);margin-inline-end:6px}
.hday[open] summary::before{content:'▾'}
.hday summary>span:first-child{flex:1}
.hitem{display:flex;align-items:center;gap:10px;padding:8px 10px;margin:0 0 6px;border-radius:10px;background:rgba(255,255,255,.03)}
.hitem .bwhat{flex:1;display:flex;flex-direction:column}
.hitem .bwhat small{font-size:12px;color:var(--mut)}
